import sys
from collections import defaultdict

def find(parent, i):
    if parent[i] == i:
        return i
    parent[i] = find(parent, parent[i])
    return parent[i]

def union(parent, rank, x, y):
    xroot = find(parent, x)
    yroot = find(parent, y)
    if rank[xroot] < rank[yroot]:
        parent[xroot] = yroot
    elif rank[xroot] > rank[yroot]:
        parent[yroot] = xroot
    else:
        parent[yroot] = xroot
        rank[xroot] += 1

def dfs(graph, u, visited, component):
    visited[u] = True
    component.append(u)
    for v in graph[u]:
        if not visited[v]:
            dfs(graph, v, visited, component)

def count_critical_links(N, M, P, edges):
    parent = list(range(N + 1))
    rank = [0] * (N + 1)
    for u, v in edges:
        union(parent, rank, u, v)
    components = defaultdict(list)
    visited = [False] * (N + 1)
    for u in range(1, N + 1):
        root = find(parent, u)
        if not visited[u]:
            dfs(graph, u, visited, components[root])
    critical_links = 0
    for u, v in edges:
        if abs(len(components[find(parent, u)]) - len(components[find(parent, v)])) < P:
            critical_links += 1
    return critical_links

